function getLang(){ try{
  // Une page peut IMPOSER sa langue via <html data-lang="en"> (coques EN des outils
  // portés : /en/relic-calc, /en/relics-tonight) — prioritaire sur la préférence globale,
  // sans la modifier. Sinon : préférence utilisateur (localStorage), défaut FR.
  const f=document.documentElement.getAttribute("data-lang"); if(I18N[f])return f;
  const l=localStorage.getItem("lang");return I18N[l]?l:"fr";}catch(e){return "fr";} }
function setLang(l){ try{if(I18N[l])localStorage.setItem("lang",l);}catch(e){} }
function t(key,vars){
  const l=getLang();
  let s=(I18N[l]&&I18N[l][key]!=null)?I18N[l][key]:((I18N.fr[key]!=null)?I18N.fr[key]:key);
  if(vars) for(const k in vars) s=s.split("{"+k+"}").join(vars[k]);
  return s;
}
/* Alias de t() pour les contextes où une variable locale "t" masque la fonction. */
const tr=t;
/* Code langue pour les API qui le supportent (WarframeStat). */
function apiLang(){ return getLang(); }
/* Traduit les éléments statiques marqués data-i18n (textContent) + <html lang>. */
function applyStaticI18n(root){
  (root||document).querySelectorAll("[data-i18n]").forEach(el=>{ el.textContent=t(el.getAttribute("data-i18n")); });
  (root||document).querySelectorAll("[data-i18n-aria]").forEach(el=>{ el.setAttribute("aria-label",t(el.getAttribute("data-i18n-aria"))); });
  (root||document).querySelectorAll("[data-i18n-ph]").forEach(el=>{ el.setAttribute("placeholder",t(el.getAttribute("data-i18n-ph"))); });
  try{document.documentElement.lang=getLang();}catch(e){}
}
